create table if not exists spiritual.dua_lists ( id bigint generated always as identity primary key, title text not null, description text, category text check (category in ('morning', 'evening', 'sleep', 'waking', 'eating', 'travel', 'prayer', 'ramadan', 'hajj', 'protection', 'provision', 'forgiveness', 'custom')), source text, is_public boolean default true, user_id uuid references identity.profiles (id), tenant_id uuid references core.tenants (id), created_at timestamptz default now(), updated_at timestamptz default now() );
